import {platformScreens} from '/platform.js?v=14';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',crown:'<path d="m2 7 5 4 5-8 5 8 5-4-3 13H5L2 7Zm3 10h14"/>',flag:'<path d="M4 22V3m0 1c5-5 11 5 16 0v11c-5 5-11-5-16 0"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',book:'<path d="M12 5v16m0-16C8 2 4 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-6-2-10 1Z"/>',screen:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/>',settings:'<path d="m9 3-1 3-3 1-2 5 3 2 1 3 5 4 3-3 3-1 3-5-3-2-1-3-5-4-3 3Z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',shield:'<path d="m12 2 9 4v7c0 5-9 9-9 9s-9-4-9-9V6l9-4Z"/><path d="m8 12 3 3 5-6"/>'};const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.flag}</svg>`;
let jinnState=null,lbTab='bazaar',combined=null;let state=null,page=location.pathname.slice(1)||'overview',offset=0,alloc=[],votes=[],draftKey='',lastRenderKey='',connected=true;
const platform=platformScreens({esc,fmt,heading,roundPanel,api,sync,toast,modal,go,getState:()=>state,getMarket:()=>jinnState,getOwn:()=>own()});
const phaseName={lobby:'Awaiting the first round',proposal:'The negotiation',voting:'Anonymous voting',results:'The verdict',deployment:'Deploy your army',battle:'Battle reveal',between:'Round complete',finished:'Event complete'};
// The player's own table merged with the shared game clock: every table is in the same phase at the same time.
const own=()=>{if(!state?.mine)return null;let t=state.tables.find(t=>t.id===state.mine.table);return {...state.game,...state.mine,id:'game',name:state.mine.tableName,teams:t.seats,size:t.seats.length,locked:t.locked};};
const tableName=p=>state.tables.find(t=>t.id===p.table)?.name||'—';
const ranked=()=>state.players.map(p=>({...p,group:tableName(p)})).sort((a,b)=>b.score-a.score||b.wins-a.wins||(b.history.at(-1)||0)-(a.history.at(-1)||0));
async function api(url,data){let r=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let o=await r.json();if(!r.ok)throw Error(o.error||'Request failed');return o;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
let enrollAt={bazaar:0,jinn:0};
async function sync(force=false){try{let previous=own(),previousMarket=jinnState?.round,next=await api('/api/state');
// Signing in is all a player does: the server creates their player record the first time they arrive.
if(next.user&&next.role!=='admin'&&!next.teamId&&Date.now()-enrollAt.bazaar>15000){enrollAt.bazaar=Date.now();try{await api('/api/enroll',{});next=await api('/api/state');}catch{}}
let market=next.backend?.jinnfire?await api('/api/jinn/state').catch(()=>({enabled:false})):{enabled:false};
if(market.enabled&&!market.mine&&next.role!=='admin'&&next.role!=='public'&&Date.now()-enrollAt.jinn>15000){enrollAt.jinn=Date.now();try{await api('/api/jinn/enroll',{});market=await api('/api/jinn/state');}catch{}}
jinnState=market;if((page==='leaderboard'&&lbTab==='combined')||page==='display'||page==='jinnfire-display')combined=await api('/api/leaderboards').catch(()=>combined);offset=next.serverTime-Date.now();let key=JSON.stringify({...next,serverTime:0,combined,lbTab,jinn:{...market,serverTime:0},game:{...next.game,remaining:next.game.paused?next.game.remaining:undefined}});state=next;connected=true;if(force||key!==lastRenderKey){let editing=document.activeElement?.matches('.allocator input,.form input,.form select,.form textarea,[data-allow-filter],[data-seat],[data-seat-add],#market-quantity'),current=own();if(force||!editing||previous?.phase!==current?.phase||previous?.round!==current?.round||previousMarket?.status!==jinnState?.round?.status||previousMarket?.id!==jinnState?.round?.id){lastRenderKey=key;render();}}clock();}catch{connected=false;clock();}}
function go(p){page=p;history.pushState({},'',p==='overview'?'/':'/'+p);render();window.scrollTo({top:0,behavior:'smooth'});}
function time(g){if(!g?.deadline)return '--:--';let seconds=Math.max(0,Math.ceil((g.paused?g.remaining:g.deadline-Date.now()-offset)/1000));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function clock(){let r=jinnState?.round;document.querySelectorAll('[data-market-clock]').forEach(el=>{let seconds=r?.status==='live'?Math.max(0,Math.ceil((r.paused?r.remainingMs:new Date(r.deadline).getTime()-Date.now()-offset)/1000)):r?.status==='ready'?120:null;el.textContent=seconds===null?'--:--':String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');el.classList.toggle('clock-warning',seconds!==null&&seconds<=20);document.querySelectorAll('[data-market-clock-label]').forEach(label=>label.textContent=r?.paused?'Paused for all players':seconds===0?'Time is up — entries closed':r?.status==='live'?(seconds<=20?'Final 20 seconds':'Time remaining'):r?.status==='ready'?'Round not started':'Round closed');if(seconds===0)document.querySelectorAll('#market-production-form input,#market-production-form button').forEach(input=>input.disabled=true);});document.querySelectorAll('[data-clock]').forEach(e=>{e.textContent=time(state?.game);});document.querySelectorAll('.connection').forEach(e=>{e.hidden=connected;e.classList.toggle('offline',!connected);e.innerHTML=connected?'':'<span class="dot" style="background:#eaa9a4"></span>Reconnecting…';});}
function shell(content){let nav=[['games','grid','Games'],['overview','grid','Command centre'],['team','shield','My seat'],['tables','users','The tables'],['leaderboard','crown','Leaderboard'],['rules','book','How to play'],['display','screen','Projector'],...(state.settings.jinnfireOpen||state.role==='admin'?[['jinnfire','flag','Jinnfire']]:[]),...(state.role==='admin'?[['admin','settings','Admin panel']]:[])];let me=state.players.find(p=>p.id===state.teamId)||jinnState?.mine;return `<div class="shell"><aside class="sidebar"><a href="/" data-page="overview" class="brand"><div class="brand-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M19 3a13 13 0 1 0 10 21A11 11 0 1 1 19 3z" fill="currentColor"/><path d="m24 7 1.2 3 3 1.2-3 1.2-1.2 3-1.2-3-3-1.2 3-1.2z" fill="currentColor"/></svg></div><div class="brand-title"><img src="/bazaar-bluff-title.svg" alt="Bazaar Bluff" width="461" height="290"><span>OASIS ’26</span></div></a><nav class="nav">${nav.map(([p,i,l])=>`<a href="/${p==='overview'?'':p}" data-page="${p}" class="${page===p?'active':''}" title="${l}">${icon(i)}<span>${l}</span>${p==='tables'?`<b class="count">${state.tables.length}</b>`:''}</a>`).join('')}${state.role==='admin'?`<a href="/settings" data-page="settings" class="${page==='settings'?'active':''}">${icon('settings')}<span>Event settings</span></a>`:''}</nav><div class="side-bottom"><div class="edition"><h4>Dawn of the Djinns</h4><p>Oasis ’26 · 54th edition<br>30 October · 1 PM · NAB 6156</p></div><button class="account" style="background:none;width:100%;text-align:left" ${state.role==='public'?'':state.teamId&&state.role!=='admin'?'data-page="profile"':'data-action="logout"'}><span class="avatar">${state.role==='admin'?'AD':me?esc(me.name.slice(0,2).toUpperCase()):'OB'}</span><span class="details">${state.role==='admin'?'Event organiser':me?esc(me.name):state.user?esc(state.user.name):'Observer mode'}<span style="display:block;margin-top:4px;color:var(--muted);font-size:9px">${state.role==='public'?'':state.teamId&&state.role!=='admin'?'Profile ↗':'Sign out ↗'}</span></span></button></div></aside><div class="workspace"><header class="topbar"><div class="crumb">Oasis ’26 <span style="color:#564863;margin:0 12px">/</span><span>${({overview:'Command centre',team:'Your headquarters',tables:'The tables',leaderboard:'Hall of fortune',rules:'The rulebook',settings:'Event settings',event:'The event',admin:'Admin panel',profile:'Your profile',games:'Games',jinnfire:'Jinnfire Exchange'})[page]||'Command centre'}</span></div><a class="mobile-brand" href="/" data-page="overview"><img src="/bazaar-bluff-title.svg" alt="Bazaar Bluff" width="461" height="290"></a><div class="top-right"><span class="connection" role="status" hidden></span><button class="ghost" data-action="${state.role==='public'?'join':'poster'}">${state.role==='public'?'Enter the bazaar ↗':'Event details ↗'}</button></div></header><main class="content animate-in">${content}</main></div></div>`;}
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const realmLore=[
 {title:'The Citadel',description:'Check the points available here, then decide how much of your army to commit.',x:48,y:30,kind:'TERRITORY DETAILS',glyph:'♜'},
 {title:'Iron Harbour',description:'Deploy more troops than the other teams to win this territory’s points.',x:82,y:44,kind:'TERRITORY DETAILS',glyph:'⚓'},
 {title:'High Ridge',description:'Compare this territory’s value with your remaining troops before deploying.',x:72,y:73,kind:'TERRITORY DETAILS',glyph:'♝'},
 {title:'The Crossroads',description:'Your troops stay here for this round. Armies reset before the next proposal.',x:33,y:70,kind:'TERRITORY DETAILS',glyph:'✧'},
 {title:'Outpost',description:'Lower-value territories can still decide a close round. The same scoring rules apply here.',x:16,y:41,kind:'TERRITORY DETAILS',glyph:'⚑'}
];
let selectedTerritory=0;document.documentElement.dataset.motion='on';
// The three gold-line cards from the Oasis ’26 poster: Bluffs, Deals and More!
const cardIcons={palm:'<path d="M2 58c3-26 1-52-4-76" fill="none" stroke="url(#oa-gold)" stroke-width="6" stroke-linecap="round"/><path d="M-2-20c-12-14-34-16-46-4 14-6 30-4 46 4zM-2-20c14-16 36-16 48-2-14-6-32-6-48 2zM-2-20c-6-20-24-30-40-26 16 2 30 12 40 26zM-2-20c8-20 28-28 44-22-16 0-32 8-44 22zM-2-20c-18 2-32 16-36 32 8-14 20-24 36-32zM-2-20c18 0 32 12 38 28-10-12-22-22-38-28z" fill="url(#oa-gold)"/><circle cx="-6" cy="-14" r="4" fill="url(#oa-gold)"/><circle cx="3" cy="-12" r="4" fill="url(#oa-gold)"/><ellipse cx="2" cy="60" rx="26" ry="5" fill="url(#oa-gold)"/>',
lamp:'<path d="M62-26c8-10-6-16 2-26s-4-16 4-24" fill="none" stroke="#f6dc94" stroke-width="2" stroke-linecap="round" opacity=".7"/><path d="M-38 14c0-16 22-24 40-22 16 2 26 8 34 4 8-4 16-14 26-20-4 12-12 26-24 34-10 8-26 12-42 12-18 0-34-2-34-8z" fill="url(#oa-gold)"/><path d="M-38 8c-16-6-24 12-10 20" fill="none" stroke="url(#oa-gold)" stroke-width="4" stroke-linecap="round"/><path d="M-14-6c2-12 22-12 24 0z" fill="url(#oa-gold)"/><circle cx="-2" cy="-16" r="4" fill="url(#oa-gold)"/><path d="M-12 26h20l6 12h-32z" fill="url(#oa-gold)"/><path d="M-24 40h44" stroke="url(#oa-gold)" stroke-width="4" stroke-linecap="round"/>',
gem:'<path d="M-24-34h48l18 22-42 52-42-52z" fill="url(#oa-gold)"/><path d="M-24-34l10 22h-28z" fill="#fff6d0" opacity=".4"/><path d="M-42-12h84M-24-34l10 22 14-22 14 22 10-22M-14-12 0 40 14-12" fill="none" stroke="#7a4a12" stroke-width="1.6" stroke-linejoin="round" opacity=".75"/><path d="m40-50 2 6 6 2-6 2-2 6-2-6-6-2 6-2z" fill="#fff3cf"/>'};
function card(x,y,turn,index,label,iconName){let flourish='<path d="M-60-58c0-20 8-32 28-32M-60-58c5-5 11-4 12 1-1 4-6 5-8 2M-32-90c5 4 4 10-1 12-4-1-5-6-2-8" fill="none" stroke="#f2c55c" stroke-width="1.1" stroke-opacity=".85"/>';return `<g class="oa-float"><g transform="translate(${x} ${y}) rotate(${turn})"><rect x="-74" y="-104" width="148" height="208" rx="10" fill="#121835" fill-opacity=".72" stroke="url(#oa-gold)" stroke-width="2.6"/><rect x="-64" y="-94" width="128" height="188" rx="5" fill="none" stroke="#f2c55c" stroke-opacity=".5" stroke-width=".9"/><g transform="scale(-1 1)">${flourish}</g><g transform="scale(1 -1)">${flourish}</g><text x="-50" y="-70" class="oa-index">${index}</text><text x="50" y="70" class="oa-index" transform="rotate(180 50 70)">${index}</text><text y="-52" class="oa-label">${label}</text><g transform="translate(0 22) scale(.82)">${cardIcons[iconName]}</g></g></g>`;}
function art(){return `<svg class="oasis-cards" viewBox="0 0 600 440" role="img" aria-label="Three gold playing cards: Bluffs, Deals and More"><defs><linearGradient id="oa-gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffe9a6"/><stop offset=".55" stop-color="#f0c158"/><stop offset="1" stop-color="#c28a2c"/></linearGradient><radialGradient id="oa-halo"><stop offset="0" stop-color="#f2c55c" stop-opacity=".28"/><stop offset="1" stop-color="#f2c55c" stop-opacity="0"/></radialGradient></defs><ellipse cx="300" cy="240" rx="280" ry="170" fill="url(#oa-halo)"/><path d="M520 34a24 24 0 1 0 18 41 20 20 0 1 1-18-41z" fill="#f7e3a8"/><g fill="#fff3cf" class="oa-twinkle"><path d="m80 60 2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/><path d="m452 26 1.5 4.5 4.5 1.5-4.5 1.5-1.5 4.5-1.5-4.5-4.5-1.5 4.5-1.5z"/><circle cx="40" cy="170" r="1.6"/><circle cx="572" cy="150" r="1.4"/><circle cx="210" cy="30" r="1.2"/></g>${card(160,238,-14,'A','BLUFFS','palm')}${card(440,238,14,'10','MORE!','gem')}${card(300,214,0,'7','DEALS','lamp')}</svg>`;}
function territoryInfo(i){let f=state.settings.fields[i],l=realmLore[i];return `<span class="territory-emblem">${l.glyph}</span><div class="territory-copy"><span class="eyebrow">${l.kind}</span><h4>${l.title}</h4><p>${l.description}</p></div><div class="territory-value"><strong>${fmt(f.value)}</strong><span>BATTLE POINTS</span></div>`;}
function mapSvg(expanded=false){return `<div class="realm-atlas ${expanded?'atlas-expanded':''}" data-map><img class="atlas-image" src="/artwork/five-realms.webp" width="1536" height="1024" alt="A painted realm with a golden citadel, coastal harbour, mountain fortress, caravan crossroads and desert watchtower" loading="${expanded?'eager':'lazy'}"><svg class="atlas-routes" viewBox="0 0 1000 667" preserveAspectRatio="none" aria-hidden="true"><path class="route-path" d="M160 274 480 200 820 294 720 487 330 467 160 274M480 200 720 487M480 200 330 467"/></svg>${state.settings.fields.map((f,i)=>{let l=realmLore[i];return `<button class="territory-marker ${selectedTerritory===i?'selected':''}" style="--x:${l.x}%;--y:${l.y}%" data-territory="${i}" aria-label="Explore ${esc(f.name)}, ${f.value} battle points" aria-pressed="${selectedTerritory===i}"><span class="territory-pin"><span>${l.glyph}</span></span><span class="territory-name">${esc(f.name)}<small>${fmt(f.value)} <span>PTS</span></small></span></button>`;}).join('')}${!expanded?'<button class="expand-map" data-action="expand-map" aria-label="Expand battlefield map">⛶ <span>Explore map</span></button>':''}</div><div class="territory-intel" aria-live="polite">${territoryInfo(selectedTerritory)}</div>`;}

function overview(){let g=state.game;return `<section class="hero oasis-hero"><div class="hero-copy"><div class="eyebrow">Oasis ’26 · Dawn of the Djinns</div><h1 class="hero-title"><img src="/bazaar-bluff-title.svg" alt="Bazaar Bluff" width="461" height="290"></h1><p>Split the pot with the other players at your table, vote on the deal, then send your troops to five territories.</p><dl class="hero-facts"><div><dt>Prize pool</dt><dd>₹13K</dd></div><div><dt>Date</dt><dd>30 Oct · 1 PM</dd></div><div><dt>Venue</dt><dd>NAB 6156</dd></div></dl><div class="hero-actions"><button class="primary" data-action="${state.teamId?'myteam':'join'}">${state.teamId?'Your seat':'Enter the bazaar'} ↗</button><button class="text-button" data-action="rules">How to play <span class="gold">→</span></button></div></div><div class="hero-art">${art()}</div></section><div class="stats">${[['users','Players',state.players.length,'players','Signed in with Google'],['grid','Tables',state.tables.length,'tables','Four or five players per table'],['flag','Points available',fmt(state.settings.fields.reduce((s,f)=>s+f.value,0)),'/ round','Total across five battlefields'],['clock','Current round',g.round,`/ ${state.settings.rounds} rounds`,phaseName[g.phase]]].map(([i,l,n,u,f])=>`<div class="stat"><div class="stat-head">${l}${icon(i)}</div><div class="stat-number">${n} <span>${u}</span></div><div class="stat-foot">${f}</div></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h3>The battlefield</h3><p class="panel-sub">Select a territory to see its value.</p></div><span class="tag">${fmt(state.settings.pot)} TROOP POOL</span></div><div class="map premium-map">${mapSvg()}</div></section>${roundPanel()}</div><div class="section-head"><div><h3>The tables <span class="muted small">/ ${state.tables.length.toString().padStart(2,'0')}</span></h3><p>Every table plays the same round at the same time.</p></div><button class="ghost" data-action="tables">View all tables ↗</button></div><div class="group-grid">${state.tables.slice(0,4).map(tableCard).join('')}</div>${leaderTable(5,true)}`;}
function roundPanel(){let g=state.game,admin=state.role==='admin',m=own(),phases=['proposal','voting','results','deployment','battle'],live=['proposal','voting','results','deployment','battle'].includes(g.phase),seated=state.players.filter(p=>p.table).length,locked=state.tables.reduce((n,t)=>n+t.locked,0),done=live?locked:seated,total=live?seated:state.players.length,waiting=g.phase==='lobby'?'Waiting for the organiser to start round 1.':g.phase==='between'?`Round ${g.round+1} starts when the organiser begins it.`:g.phase==='finished'?'All rounds are played.':'';
return `<section class="panel"><div class="panel-heading"><h3>Round control</h3><span class="tag">${g.phase==='lobby'?'NOT STARTED':'LIVE EVENT'}</span></div><div class="phase-card"><div><div class="eyebrow" style="font-size:8px">ROUND ${g.round} OF ${state.settings.rounds}</div><h4>${phaseName[g.phase]}</h4><p>${g.paused?'Timer paused for every table':esc(waiting||'Every table is in this phase together.')}</p></div><div class="timer" data-clock="game">${time(g)}</div></div><div class="phase-steps">${phases.map((p,i)=>`<div class="step ${g.phase===p?'current':''}"><i>${i+1}</i>${['Propose','Vote','Verdict','Deploy','Battle'][i]}</div>`).join('')}</div><div class="readiness"><span>${live?'Entries locked in':'Players seated'}</span><span>${done} / ${total}</span></div><div class="progress"><div style="width:${total?100*done/total:0}%"></div></div>${m?`<div class="seats">${m.teams.map((t,i)=>`<div class="seat"><span class="avatar">${String.fromCharCode(65+i)}</span><span>${esc(t.name)}</span><b>${fmt(t.score)} pts</b></div>`).join('')}</div>`:''}<div class="control-buttons">${admin?(live?`<button class="ghost" data-control="pause">${g.paused?'▶ Resume':'Ⅱ Pause'}</button><button class="ghost" data-control="extend">+1 min</button><button class="primary" data-control="advance">Next phase →</button>`:g.phase==='finished'?'<button class="ghost" data-control="add-round">+ Add a round</button>':`<button class="primary" data-control="start-round">Start round ${g.round+1} for every table ↗</button>`):`<button class="ghost" data-action="${state.teamId?'myteam':'join'}">${state.teamId?'Go to your seat ↗':'Sign in to play ↗'}</button>`}</div></section>`;}
function tableCard(t){return `<button class="group-card" data-table="${t.id}"><div class="group-top"><strong>${esc(t.name)}</strong><span class="status">${state.game.phase==='lobby'?'LOBBY':state.game.phase.toUpperCase()}</span></div><div class="group-symbol"><span>${['♜','♞','♛','♝','♟','✧','☾','♖'][state.tables.indexOf(t)%8]}</span><span class="small">${t.seats.length} PLAYERS</span></div><div class="group-bottom"><div class="team-dots">${t.seats.map((s,i)=>`<span title="${esc(s.name)}">${String.fromCharCode(65+i)}</span>`).join('')}</div><span>${t.seats.map(s=>esc(s.name)).join(' · ')||'No players yet'}</span></div></button>`;}
function leaderTable(limit=100,compact=false){let rows=ranked().slice(0,limit);return `<section class="panel ${compact?'leaderboard':''}"><div class="panel-heading"><div><h3>${compact?'Leaderboard':'Leaderboard'}</h3><p class="panel-sub">Ranked by points, territories won, then latest round</p></div>${compact?'<a href="/leaderboard" data-page="leaderboard">Full leaderboard ↗</a>':''}</div><table class="table"><thead><tr><th>#</th><th>Player</th><th class="hide-mobile">Table</th><th class="hide-mobile">Territories</th><th style="text-align:right">Battle points</th></tr></thead><tbody>${rows.map((t,i)=>`<tr class="${t.id===state.teamId?'me':''}"><td class="rank">${i+1}</td><td>${esc(t.name)} ${t.id===state.teamId?'<span class="gold small"> · You</span>':''}</td><td class="hide-mobile muted">${esc(t.group)}</td><td class="hide-mobile muted">${t.wins}</td><td class="score">${fmt(t.score)} <span class="muted small">pts</span></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">Scores will appear after the first battle.</div>':''}</section>`;}
function teamPage(){let g=own();if(!g){let seatless=state.role==='admin'?['ORGANISER','Organisers run the event','Open the admin panel to seat players and start rounds.','<a class="primary platform-link" href="/admin" data-page="admin">Open admin panel ↗</a>']:state.teamId?['YOUR PLACE AT THE TABLE','Waiting for your seat','The organiser seats every player at a table before the round starts. This page updates by itself.','']:['YOUR PLACE AT THE TABLE','Sign in to play','Use the Google account your organiser added to the sign-in list. The organiser seats you at a table.','<button class="primary" data-action="join">Sign in ↗</button>'];return heading(seatless[0],seatless[1],seatless[2])+`<div class="poster-layout"><div class="panel" style="padding:35px"><h2 class="display-title">Take your seat.</h2><p class="muted" style="line-height:1.9">${state.teamId?`You are signed in${state.user?' as '+esc(state.user.email):''}. Round ${state.game.round+1} starts for every table at once, when the organiser begins it.`:'Players sign in with Google. There are no codes or PINs to remember.'}</p>${seatless[3]}</div><div class="card-stage">${art()}</div></div>`;}
let t=g.teams[g.slot],key=`${g.table}:${g.round}:${g.phase}`;if(key!==draftKey){draftKey=key;let stored;try{stored=JSON.parse(localStorage.getItem('draft:'+key)||'null');}catch{}let slots=g.phase==='proposal'?g.size:5,saved=stored?.alloc||g.entry?.[g.phase==='proposal'?'proposal':'deployment']||[];alloc=Array.from({length:slots},(_,i)=>Number.isSafeInteger(saved[i])&&saved[i]>0?saved[i]:0);let savedVotes=stored?.votes||g.entry?.votes||[];votes=Array.from({length:g.proposals?.length||0},(_,i)=>savedVotes[i]===true);}
let waiting=g.phase==='lobby'?`<section class="panel"><div class="panel-heading"><h3>Your table is assembling</h3><span class="tag">${g.size} PLAYERS</span></div>${g.teams.map((s,i)=>`<div class="battle-row"><span class="avatar">${String.fromCharCode(65+i)}</span><span style="flex:1">${esc(s.name)}</span><span class="small muted">${s.id===state.teamId?'You':'Seated'}</span></div>`).join('')}<div class="empty">Round 1 starts for every table at the same moment, when the organiser begins it.</div></section>`:g.phase==='between'?`${g.battle?battlePage(g):''}<section class="panel"><div class="empty">Round ${g.round} is complete. Round ${g.round+1} starts for every table when the organiser begins it.</div></section>${leaderTable(10)}`:'';
return `<div class="team-page">${heading('YOUR SEAT',esc(t.name),'Your proposal, votes, and troop deployment stay private.')}<div class="team-banner"><div><div class="eyebrow">${esc(g.name)} · SEAT ${String.fromCharCode(65+g.slot)}</div><h2>${phaseName[g.phase]}</h2><span class="small muted">Round ${g.round} / ${state.settings.rounds} · ${fmt(t.score)} points</span></div><div style="text-align:right"><div class="timer" data-clock="game">${time(g)}</div><div class="small muted">${g.paused?'Paused for every table':'Server time'}</div></div></div>${waiting||(['proposal','deployment'].includes(g.phase)?allocation(g):g.phase==='voting'?votePage(g):g.phase==='results'?results(g):g.phase==='battle'?battlePage(g):leaderTable())}</div>`;}


function allocation(g){let proposal=g.phase==='proposal',total=proposal?state.settings.pot:g.army;return `<section class="panel"><div class="panel-heading"><div><h3>${proposal?'Write your proposal':'Choose your battles'}</h3><p class="panel-sub">${proposal?'Split the pot. Convince the table. Keep your intentions hidden.':'The highest troop count wins each territory. Unused troops are lost.'}</p></div><span class="tag">${total} ${proposal?'POINTS':'TROOPS'}</span></div><div class="allocator">${Array.from({length:proposal?g.size:5},(_,i)=>`<div class="allocation-row"><span class="avatar">${proposal?String.fromCharCode(65+i):['♜','⚓','♝','✧','⚑'][i]}</span><div><label for="num-${i}">${proposal?esc(g.teams[i]?.name||'Team '+String.fromCharCode(65+i)):esc(state.settings.fields[i].name)} ${!proposal?`<span class="gold small"> · ${state.settings.fields[i].value} pts</span>`:''}</label><input aria-label="${proposal?'Share':'Troops'} slider ${i+1}" type="range" min="0" max="${total}" step="1" data-alloc="${i}" value="${alloc[i]||0}" ${g.myLock?'disabled':''}></div><input id="num-${i}" aria-label="${proposal?'Share':'Troops'} ${i+1}" type="number" min="0" max="${total}" step="1" data-alloc="${i}" value="${alloc[i]||0}" ${g.myLock?'disabled':''}></div>`).join('')}<div class="allocation-bottom"><div><div id="allocation-count" class="gold"></div><div class="small muted" style="margin-top:6px">Only you can see this entry.</div></div><div class="inline"><button class="ghost" data-action="equal" ${g.myLock?'disabled':''}>${proposal?'Equal split':'Spread evenly'}</button><button class="ghost" data-action="reset" ${g.myLock?'disabled':''}>Reset</button></div></div>${lockBar(g,proposal?'proposal':'deployment')}</div></section>`;}
// One place for locking in: says where you stand, why the button is off, and what happens if the clock runs out.
function lockBar(g,what){let others=Math.max(0,(g.locked||0)-(g.myLock?1:0));return `<div class="lock-bar ${g.myLock?'is-locked':''}"><div class="lock-status"><b>${g.myLock?'✓ Locked in':'Not locked in yet'}</b><span id="lock-hint">${g.myLock?`Your ${what} is final unless you unlock it. ${others} of ${g.size-1} other players at your table are locked in.`:`Your ${what} saves as you go. Lock in to confirm it; if time runs out, the saved version counts.`}</span></div><button id="lock-entry" class="lock-button" data-action="${g.myLock?'unlock':'lock'}" ${!g.myLock&&g.paused?'disabled':''}>${g.myLock?'Unlock & edit':'Lock in '+what+' ↗'}</button></div>`;}
function votePage(g){return `<section class="panel"><div class="panel-heading"><div><h3>The table has spoken. Have your say.</h3><p class="panel-sub">Approve the proposals you support. Anything you have not approved when the clock runs out counts as a rejection. All votes remain anonymous.</p></div></div><div class="vote-grid">${g.proposals.map((p,i)=>`<article class="vote-card"><h3>Proposal ${i+1} ${p.yours?'<span class="tag">YOURS</span>':''}</h3><div class="shares">${p.shares.map((n,j)=>`<span>${String.fromCharCode(65+j)}<b>${n}</b></span>`).join('')}</div><div style="height:5px;display:flex;margin-top:17px;gap:2px">${p.shares.map((n,j)=>`<span style="width:${100*n/state.settings.pot}%;background:${['#e8c878','#ac8fd2','#8faca5','#bd849c','#aaa'][j]};border-radius:2px"></span>`).join('')}</div><div class="vote-buttons"><button class="ghost ${votes[i]?'selected':''}" data-vote="${i}" aria-pressed="${!!votes[i]}" ${g.myLock?'disabled':''}>${votes[i]?'✓ Approved':'Approve'}</button></div></article>`).join('')}</div><div style="padding:0 22px 22px"><p class="small muted">${votes.filter(Boolean).length} of ${g.proposals.length} proposals approved · Your votes only</p>${lockBar(g,'votes')}</div></section>`;}
function results(g){let won=g.outcome.winners||(g.outcome.winner>=0?[g.outcome.winner]:[]);return `<section class="panel"><div class="panel-heading"><div><h3>The verdict is in.</h3><p class="panel-sub">${!won.length?'Nobody approved a proposal, so fallback armies apply.':won.length===1?`Proposal ${won[0]+1} has the most approvals and passes.`:`Proposals ${won.map(i=>i+1).join(', ').replace(/, (\d+)$/,' and $1')} tie for the most approvals. All of them pass and their shares are added together.`}</p></div><span class="tag">YOUR ARMY: ${g.army}</span></div>${g.proposals.map((p,i)=>`<div class="result-card ${won.includes(i)?'winner':''}"><div style="display:flex;justify-content:space-between;margin-bottom:15px"><span>Proposal ${i+1}</span><span class="gold">${g.outcome.counts[i]} / ${g.size} approvals ${won.includes(i)?'✦ PASSED':''}</span></div><div class="shares">${p.shares.map((n,j)=>`<span>${String.fromCharCode(65+j)}<b>${n}</b></span>`).join('')}</div></div>`).join('')}<p class="empty">Prepare your strategy. Deployment is next.</p></section>`;}
function battlePage(g){return `<section class="panel"><div class="panel-heading"><h3>The spoils of war</h3><span class="tag">ROUND ${g.round}</span></div>${g.battle.fields.map((f,i)=>`<div class="battle-row animate-in" style="animation-delay:${i*.2}s"><div><h3>${esc(state.settings.fields[i].name)}</h3><p>${f.winners.length?f.winners.map(w=>esc(g.teams[w].name)).join(' & ')+(f.winners.length>1?' share the territory':' claims the territory'):'Nobody sent troops here, so no one scores'}</p><div class="small muted">${f.troops.map((n,j)=>String.fromCharCode(65+j)+': '+n).join(' · ')} troops</div></div><strong>+${fmt(f.points)}</strong></div>`).join('')}<div class="empty">Your round: <b class="gold">+${fmt(g.battle.scores[g.teams.findIndex(t=>t.id===state.teamId)])} points</b></div></section>`;}
function profilePage(){let me=state.players.find(p=>p.id===state.teamId);if(!me)return heading('YOUR PROFILE','Sign in to play','Your display name is shown to the other players at your table and on the leaderboard.')+'<button class="primary" data-action="join">Sign in ↗</button>';let seat=tableName(me);return heading('YOUR PROFILE','Display name','This is the name other players see at your table and on the leaderboard.')+`<section class="panel profile-panel"><form id="profile-form" class="form"><label class="field">Display name<input name="name" required maxlength="60" autocomplete="nickname" value="${esc(me.name)}" ${state.nameLocked?'readonly':''}></label><p class="small muted">${state.user?.email?'Signed in as '+esc(state.user.email)+'. ':''}${seat==='—'?'You are not seated at a table yet.':'You are seated at '+esc(seat)+'.'} ${state.nameLocked?'Your display name is locked, here and in Jinnfire Exchange. Ask an organiser if it needs correcting.':'You can choose your display name once. After you confirm it, it is locked and is also your name in Jinnfire Exchange.'}</p><div id="form-error" class="error"></div><div class="inline">${state.nameLocked?'':'<button class="primary">Choose name ↗</button>'}<button type="button" class="ghost" data-action="logout">Sign out</button></div></form></section>`;}
function tablesPage(){return heading('THE NEGOTIATING TABLES','Tables','The organiser seats every player at a table of four or five.',state.role==='admin'?'<a class="primary platform-link" href="/admin" data-page="admin">Manage tables ↗</a>':'')+`<div class="group-grid">${state.tables.map(tableCard).join('')}</div>${!state.tables.length?'<div class="panel empty">No tables yet. The organiser is setting up the event.</div>':''}${state.role==='admin'?'<div class="section-head"><h3>Event operations</h3><div class="inline"><a class="ghost" href="/api/export">Export closed rounds ↓</a></div></div>':''}`;}
function rulesPage(){return heading('THE RULEBOOK','How to play','Split the pot, vote on a proposal, and compete for five territories.')+`<div class="rules-grid">${[['01','Make a proposal',`Split a pot of ${state.settings.pot} points among all players at your table. Whole numbers only. Your proposal must allocate the entire pot. You have three minutes to negotiate.`],['02','Cast your votes','Approve the anonymous proposals you support. Anything you have not approved when the clock runs out counts as a rejection. No live tallies. No names. Nobody knows who voted for what.'],['03','Build your army',`The proposal with the most approvals passes. If proposals tie for the most, they all pass and your shares are added together. Your share becomes your army. If nobody approves anything, every player receives ${state.settings.fallback} troops.`],['04','Choose your battles','Secretly divide your army among five battlefields. Go all-in on one territory, or spread your strength. You can use fewer troops, but the leftovers are lost.'],['05','Claim your territory',`The largest army on each battlefield takes its points. ${state.settings.tie==='split'?'Tied armies split the points equally.':'Tied armies receive no points.'} A territory nobody sends troops to scores for no one. Each round starts fresh. Your score carries forward.`],['06','Win on points',`After ${state.settings.rounds} rounds, the highest battle-point total wins. Ties are broken by territories won, then points in the most recent round. `]].map(([n,t,p])=>`<article class="panel rule"><span class="num">${n} <span style="font-size:17px">✧</span></span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div><div class="panel" style="margin-top:22px"><div class="panel-heading"><h3>The five realms</h3><span class="tag">${fmt(state.settings.fields.reduce((s,f)=>s+f.value,0))} POINTS PER ROUND</span></div><div class="map premium-map rule-atlas">${mapSvg()}</div></div>`;}
function eventPage(){return heading('OASIS ’26 · 54TH EDITION','Event details','Dawn of the Djinns')+`<div class="poster-layout"><img src="/event-poster.png" alt="Bazaar Bluff event poster. Oasis ’26. Prize pool 13K. 30 October, 1 PM, NAB 6156."><div><p class="muted" style="line-height:2;margin-top:0">A strategy game of negotiation and secret decisions. Agree on a share of the pot, build an army, and compete for five territories.</p><dl class="hero-facts"><div><dt>Prize pool</dt><dd>₹13K</dd></div><div><dt>Date</dt><dd>30 Oct · 1 PM</dd></div><div><dt>Venue</dt><dd>NAB 6156</dd></div></dl><button class="primary" style="margin:4px 0 20px" data-action="join">Enter the bazaar ↗</button><div class="panel" style="padding:23px;margin-top:15px"><div class="eyebrow">YOUR ORGANISERS</div><p style="line-height:2;font-size:13px">Avadhoot · <a class="gold" href="tel:+919594401770">+91 95944 01770</a><br>Rohil · <a class="gold" href="tel:+918727916019">+91 87279 16019</a></p></div></div></div>`;}
function settingsPage(){if(state.role!=='admin')return heading('ORGANISER ACCESS','The keys to the bazaar.','Sign in to manage your event.')+'<button class="primary" data-action="admin">Organiser sign in ↗</button>';return heading('EVENT OPERATIONS','Set the stakes.','Game settings lock while real rounds are in progress.')+`<section class="panel"><form id="settings-form" class="form settings-form"><label class="field">Shared pot<input name="pot" type="number" min="1" value="${state.settings.pot}" required></label><label class="field">Number of rounds<input name="rounds" type="number" min="1" value="${state.settings.rounds}" required></label><label class="field">Fallback army<input name="fallback" type="number" min="0" value="${state.settings.fallback}" required></label><label class="field">Battlefield ties<select name="tie"><option value="split" ${state.settings.tie==='split'?'selected':''}>Split points equally</option><option value="none" ${state.settings.tie==='none'?'selected':''}>Nobody scores</option></select></label><button class="primary">Save settings ↗</button></form></section><div class="section-head"><h3>Event audit · Latest actions</h3><a href="/api/export" class="ghost small">Export closed rounds ↓</a></div><section class="panel">${(state.audit||[]).slice().reverse().map(a=>`<div class="audit"><span>${new Date(a.at).toLocaleTimeString()}</span><b>${esc(a.action)}</b><span>${esc(a.actor)}</span></div>`).join('')}</section>`;}
function displayPage(){let g=state.game,ready=state.tables.filter(t=>t.seats.length&&t.locked===t.seats.length).length;return `<main class="display-page"><header class="display-header"><a href="/" data-page="overview"><span class="eyebrow">OASIS ’26 · DAWN OF THE DJINNS</span><h1 class="display-logo"><img src="/bazaar-bluff-title.svg" alt="Bazaar Bluff" width="461" height="290"></h1></a><div style="text-align:right"><div class="tag">LIVE EVENT</div><p class="muted">Round ${g.round} / ${state.settings.rounds} · ${phaseName[g.phase]}</p></div></header><div class="display-clock" data-clock="game">${time(g)}</div><p class="muted" style="text-align:center;margin-top:-25px;margin-bottom:40px">${ready} of ${state.tables.length} tables ready · ${g.paused?'Timer paused':'Waiting for the next move'}</p>${projectorBoards()}</main>`;}
// The three leaderboards side by side for the projectors: Bazaar Bluff, Jinnfire (ranks only) and combined.
function projectorBoards(){let rows=ranked().slice(0,10),m=jinnState,jinn=(m?.enabled?m.leaderboards?.overall||[]:[]).slice(0,10),both=(combined?.rows||[]).slice(0,10),row=(rank,name,value)=>`<tr><td class="rank">${rank<=3?'♛ ':''}${rank}</td><td>${esc(name)}</td>${value===undefined?'':`<td class="score">${value}</td>`}</tr>`,panel=(title,sub,body,empty)=>`<section class="panel"><div class="panel-heading"><div><h3>${title}</h3><p class="panel-sub">${sub}</p></div></div>${body?`<table class="table"><tbody>${body}</tbody></table>`:`<div class="empty">${empty}</div>`}</section>`;
return `<div class="projector-boards">${panel('Bazaar Bluff','Battle points',rows.map((t,i)=>row(i+1,t.name,fmt(t.score))).join(''),'Scores appear after the first battle.')}${panel('Jinnfire Exchange',m?.publishedRound?'Ranks after round '+m.publishedRound:'Ranks only',jinn.map(t=>row(t.rank,t.name)).join(''),m?.enabled?'No results published yet.':'Opens after Bazaar Bluff.')}${panel('Combined','Bazaar + scaled Jinnfire'+(combined?.jinnfire?' (×'+combined.factor+')':''),both.map(r=>row(r.rank,r.name,fmt(r.combined))).join(''),combined?'Scores appear after the first battle.':'Loading…')}</div>`;}
function jinnDisplayPage(){let m=jinnState,r=m?.round,label=!m?.enabled?'Jinnfire Exchange is not open yet':r?.status==='live'?(r.paused?'Paused':'Production is open'):r?.status==='ready'?'Next round is being prepared':r?.status==='settled'||r?.status==='published'?'Round complete':'Waiting for the organiser';return `<main class="display-page jinn-display"><header class="display-header"><a href="/" data-page="games"><span class="eyebrow">OASIS ’26 · DAWN OF THE DJINNS</span><h1>Jinnfire Exchange</h1></a><div style="text-align:right"><div class="tag">LIVE EVENT</div><p class="muted">${r?'Round '+r.number+' · ':''}${label}</p></div></header><div class="display-clock" data-market-clock>--:--</div><p class="muted" data-market-clock-label style="text-align:center;margin-top:-25px;margin-bottom:30px"></p>${r&&r.demand!==null&&r.status!=='published'?`<p class="jinn-display-demand">Market demand: <strong>${r.demand}</strong> phials</p>`:r?.demandHidden&&r.status!=='published'?'<p class="jinn-display-demand">Market demand: <strong>hidden</strong></p>':''}${m?.result&&r?.status==='published'?`<section class="panel jinn-display-result"><div class="panel-heading"><h3>What happened in round ${m.result.number}</h3></div>${platform.roundStory(m.result)}</section>`:''}${projectorBoards()}</main>`;}
function leaderboardsPage(){let tabs=[['bazaar','Bazaar Bluff'],['jinnfire','Jinnfire'],['combined','Combined']],jinnOpen=state.settings.jinnfireOpen||state.role==='admin',body;
if(lbTab==='jinnfire')body=jinnOpen?platform.boardTable():'<section class="panel empty">Jinnfire Exchange opens after Bazaar Bluff.</section>';
else if(lbTab==='combined')body=combinedBoard();else body=leaderTable();
return heading('THE HALL OF FORTUNE','Leaderboards','Standings update after each battle and each Jinnfire round.')+`<div class="platform-tabs lb-tabs" role="tablist">${tabs.map(([k,l])=>`<button role="tab" aria-selected="${lbTab===k}" data-lb-tab="${k}" class="${lbTab===k?'active':''}">${l}</button>`).join('')}</div>`+body;}
function combinedBoard(){if(!combined)return '<section class="panel empty">Loading the combined standings…</section>';let rows=combined.rows,me=state.players.find(p=>p.id===state.teamId)?.name;return `<section class="panel"><div class="panel-heading"><div><h3>Combined standings</h3><p class="panel-sub">${combined.jinnfire?`Bazaar Bluff points plus Jinnfire points scaled up ×${combined.factor}, so the best Jinnfire total is worth as much as the best Bazaar score.`:'Jinnfire Exchange has not opened yet, so these are Bazaar Bluff points only.'}</p></div></div><table class="table"><thead><tr><th>#</th><th>Player</th><th style="text-align:right">Bazaar</th><th style="text-align:right">Jinnfire</th><th style="text-align:right">Combined</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.name===me?'me':''}"><td class="rank">${r.rank<=3?'♛ ':''}${r.rank}</td><td>${esc(r.name)}</td><td class="score">${fmt(r.bazaar)}</td><td class="score">${fmt(r.jinnfire)}</td><td class="score">${fmt(r.combined)} <span class="muted small">pts</span></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">Scores will appear after the first battle.</div>':''}</section>`;}
let nameAsked=false;
// One chance to pick a display name (step 1), then a confirm box (step 2) that locks it for the rest of the event.
function nameDialog(step,name=''){let me=state.players.find(p=>p.id===state.teamId);name=name||me?.name||'';$('#modal').innerHTML=`<div class="modal-shade"><section class="modal-card" role="dialog" aria-modal="true" aria-label="Display name"><button class="close" data-action="close" aria-label="Close">×</button>${step===1?`<div class="eyebrow">WELCOME</div><h2>Choose your display name</h2><p>This is the name other players see at your table, on the leaderboard and in Jinnfire Exchange. You can change it <b>once</b>, now. After you confirm, it is locked.</p><form id="profile-form" class="form"><label class="field">Display name<input name="name" required maxlength="60" autocomplete="nickname" value="${esc(name)}"></label><div class="inline"><button class="primary">Continue</button><button type="button" class="ghost" data-action="close">Decide later</button></div></form>`:`<div class="eyebrow">PLEASE CONFIRM</div><h2>Lock in “${esc(name)}”?</h2><p>This will be your name at the tables, on the leaderboard and in Jinnfire Exchange. <b>You cannot change it afterwards.</b></p><div class="inline confirm-actions"><button class="ghost" data-name-back="${esc(name)}">Go back</button><button class="primary" data-name-confirm="${esc(name)}">Yes, lock it in</button></div>`}</section></div>`;setTimeout(()=>$('#modal input,#modal .primary')?.focus(),30);}
function askName(){if(nameAsked||!state?.teamId||state.nameLocked!==false||state.role==='admin'||page==='display'||page==='jinnfire-display')return;nameAsked=true;nameDialog(1);}
let renderedPage='';function render(){if(!state)return;let pageChanged=renderedPage!==page;renderedPage=page;$('#app').innerHTML=page==='display'?displayPage():page==='jinnfire-display'?jinnDisplayPage():shell(({overview,games:platform.gamesPage,admin:platform.adminPage,jinnfire:platform.jinnPage,team:teamPage,profile:profilePage,tables:tablesPage,leaderboard:leaderboardsPage,rules:rulesPage,event:eventPage,settings:settingsPage}[page]||overview)());if(!pageChanged){document.querySelector('.content')?.classList.remove('animate-in');document.querySelector('.content')?.classList.add('state-refresh');}updateCount();clock();askName();}
function updateCount(){let g=own();if(!g||!['proposal','deployment'].includes(g.phase))return;let proposal=g.phase==='proposal',sum=alloc.reduce((s,n)=>s+n,0),total=proposal?state.settings.pot:g.army,left=total-sum,valid=alloc.every(Number.isSafeInteger)&&alloc.every(n=>n>=0)&& (proposal?sum===total:sum<=total),plural=(n,w)=>`${n} ${w}${n===1?'':'s'}`,hint=$('#lock-hint');if(hint&&!g.myLock)hint.textContent=!valid?(proposal?(left>0?`Give out ${plural(left,'more point')} to lock in: the whole pot must be split.`:`You are ${plural(-left,'point')} over the pot.`):`You are ${plural(-left,'troop')} over your army.`):(!proposal&&left>0?`${plural(left,'troop')} will go unused and be lost. Lock in to confirm, or use them all.`:`Ready. Lock in to confirm; if time runs out, the saved version counts.`);let count=$('#allocation-count');if(count){count.textContent=g.phase==='proposal'?`Allocated ${sum} / ${total} · ${total-sum} left`:`${total-sum} troops remaining`;count.style.color=valid?'var(--green)':'var(--gold)';}let lock=$('#lock-entry');if(lock&&!g.myLock)lock.disabled=!valid||g.paused;}
function modal(type,code=''){let content='';if(type==='join')content=`<div class="eyebrow">YOUR PLACE AT THE TABLE</div><h2>Sign in to play.</h2><p>Use the Google account your organiser added to the sign-in list. The organiser seats you at a table before the first round.</p>`+platform.signIn();
if(type==='admin')content=`<div class="eyebrow">FOR THE KEEPERS OF THE BAZAAR</div><h2>Organiser access.</h2><p>Run the event, seat players, and control every round.</p><form id="admin-form" class="form"><label class="field">Organiser password<input type="password" name="password" autocomplete="current-password" required placeholder="Your private event password"></label><div id="form-error" class="error"></div><button class="primary">Open the command centre ↗</button></form>`;

if(type==='admin'&&state.backend?.google)content='<h2>Organiser sign-in</h2><p>Use an approved Google account for event administration.</p><a class="google-button" href="/auth/google"><span class="google-g">G</span>Continue with Google</a>'+(state.backend.localAdmin?'<div class="local-login-note">Local development access</div>'+content:'');$('#modal').innerHTML=`<div class="modal-shade"><section class="modal-card" role="dialog" aria-modal="true" aria-label="${type}"><button class="close" data-action="close" aria-label="Close dialog">×</button>${content}</section></div>`;setTimeout(()=>$('#modal input')?.focus(),30);}
// Moves that cannot be undone ask first. `from` lets the server refuse if the phase changed while the box was open.
const nextPhase=g=>({proposal:'voting',voting:'results',results:'deployment',deployment:'battle',battle:g.round>=state.settings.rounds?'finished':'between'})[g.phase];
const advanceNote={proposal:'Players without a saved proposal will have none.',voting:'Proposals a player has not approved count as rejections.',deployment:'Players without saved troops spread their army evenly.'};
function confirmControl(action){let g=state.game,seated=state.players.filter(p=>p.table).length,locked=state.tables.reduce((n,t)=>n+t.locked,0),body,yes,from;
if(action==='advance'){from=g.phase;body=`<h2>Move to “${phaseName[nextPhase(g)]}”?</h2><p>Every table leaves “${phaseName[g.phase]}” right now. This cannot be undone.</p><p class="small muted">${locked} of ${seated} players have locked in. Entries that are not locked in use the last saved draft. ${advanceNote[g.phase]||''}</p>`;yes='Yes, next phase';}
else if(action==='start-round'){body=`<h2>Start round ${g.round+1}?</h2><p>${state.tables.length===1?'Your one table':'All '+state.tables.length+' tables'} (${seated} players) ${state.tables.length===1?'begins':'begin'} together and tables lock until the round ends. This cannot be undone.</p>`;yes=`Yes, start round ${g.round+1}`;}
else return control(action);
$('#modal').innerHTML=`<div class="modal-shade"><section class="modal-card" role="dialog" aria-modal="true" aria-label="Confirm"><button class="close" data-action="close" aria-label="Close">×</button><div class="eyebrow">PLEASE CONFIRM</div>${body}<div class="inline confirm-actions"><button class="ghost" data-action="close" id="confirm-cancel">Cancel</button><button class="primary" data-confirm-control="${action}" ${from?`data-from="${from}"`:''}>${yes}</button></div></section></div>`;setTimeout(()=>$('#confirm-cancel')?.focus(),30);}
async function control(action,extra={}){try{await api('/api/control',{action,...extra});await sync(true);toast(({'start-round':'Round started for every table.',advance:'The next move is yours.'})[action]||'Event updated.');}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{try{if(await platform.onClick(e))return;}catch(error){toast(error.message);return;}let lb=e.target.closest('[data-lb-tab]');if(lb){lbTab=lb.dataset.lbTab;await sync(true);return;}let nameYes=e.target.closest('[data-name-confirm]'),nameBack=e.target.closest('[data-name-back]');if(nameBack){nameDialog(1,nameBack.dataset.nameBack);return;}if(nameYes){nameYes.disabled=true;try{await api('/api/profile',{name:nameYes.dataset.nameConfirm,confirm:true});$('#modal').innerHTML='';await sync(true);toast('Display name locked in.');}catch(error){nameYes.disabled=false;toast(error.message);}return;}
let territory=e.target.closest('[data-territory]');if(territory){selectedTerritory=Number(territory.dataset.territory);document.querySelectorAll('[data-territory]').forEach(el=>{let selected=Number(el.dataset.territory)===selectedTerritory;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});document.querySelectorAll('.territory-intel').forEach(el=>el.innerHTML=territoryInfo(selectedTerritory));return;}
let visualAction=e.target.closest('[data-action]')?.dataset.action;if(visualAction==='expand-map'){$('#modal').innerHTML=`<div class="modal-shade atlas-shade"><section class="atlas-dialog" role="dialog" aria-modal="true" aria-label="Explore the five realms"><div class="atlas-dialog-heading"><h2>Battlefield map</h2><button class="close" data-action="close" aria-label="Close map">×</button></div>${mapSvg(true)}</section></div>`;$('#modal .close').focus();return;}
let nav=e.target.closest('[data-page]');if(nav){e.preventDefault();go(nav.dataset.page);return;}let cc=e.target.closest('[data-confirm-control]');if(cc){cc.disabled=true;$('#modal').innerHTML='';await control(cc.dataset.confirmControl,cc.dataset.from?{from:cc.dataset.from}:{});return;}let c=e.target.closest('[data-control]');if(c){confirmControl(c.dataset.control);return;}let table=e.target.closest('[data-table]');if(table){let t=state.tables.find(t=>t.id===table.dataset.table);if(state.mine?.table===t.id){go('team');return;}$('#modal').innerHTML=`<div class="modal-shade"><section class="modal-card" role="dialog" aria-modal="true" aria-label="Table details"><button class="close" data-action="close" aria-label="Close">×</button><div class="eyebrow">TABLE</div><h2>${esc(t.name)}</h2><p>${t.seats.map(s=>String.fromCharCode(65+t.seats.indexOf(s))+' · '+esc(s.name)+' · '+fmt(s.score)+' pts').join('<br>')||'No players seated yet.'}</p></section></div>`;return;}



let vote=e.target.closest('[data-vote]');if(vote){votes[Number(vote.dataset.vote)]=!votes[Number(vote.dataset.vote)];persist();render();return;}
let a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;try{if(['join','admin'].includes(a))modal(a);else if(a==='close')$('#modal').innerHTML='';else if(a==='demo'){await api('/api/demo',{});await sync(true);go('team');}else if(a==='logout'){await api(state.backend?.google?'/auth/logout':'/api/logout',{});await sync(true);go('overview');}else if(a==='myteam')go('team');else if(a==='rules')go('rules');else if(a==='tables')go('tables');else if(a==='poster')go('event');else if(a==='equal'||a==='reset'){let g=own(),total=g.phase==='proposal'?state.settings.pot:g.army,n=g.phase==='proposal'?g.size:5;alloc=a==='reset'?Array(n).fill(0):Array(n).fill(Math.floor(total/n));if(a==='equal')alloc[n-1]+=total%n;persist();render();}else if(a==='lock'){let g=own();await api('/api/entry',{values:g.phase==='voting'?votes:alloc,lock:true});await sync(true);toast('Locked in. Your strategy stays secret.');}else if(a==='unlock'){await api('/api/entry',{unlock:true});await sync(true);}}catch(e){toast(e.message);}});
function persist(){try{localStorage.setItem('draft:'+draftKey,JSON.stringify({alloc,votes}));}catch{}scheduleSave();}
let saveTimer;function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{let g=own();if(g&&!g.myLock&&['proposal','voting','deployment'].includes(g.phase)){let values=g.phase==='voting'?votes:alloc;let valid=g.phase==='voting'?values.every(v=>typeof v==='boolean'):values.every(n=>Number.isSafeInteger(n)&&n>=0)&&(g.phase==='proposal'?values.reduce((s,n)=>s+n,0)===state.settings.pot:values.reduce((s,n)=>s+n,0)<=g.army);if(valid)try{await api('/api/entry',{values,lock:false});}catch{}}},600);}
document.addEventListener('input',e=>{platform.onInput(e);if(e.target.matches('[data-alloc]')){let g=own(),i=Number(e.target.dataset.alloc),total=g.phase==='proposal'?state.settings.pot:g.army,others=alloc.reduce((s,n,j)=>j===i?s:s+n,0),raw=e.target.value,v=Math.floor(Number(raw));
// Whole numbers only: never below zero, and never more than the pot (or army) has left after the other rows.
v=Number.isFinite(v)?Math.max(0,Math.min(v,total-others)):0;alloc[i]=v;document.querySelectorAll(`[data-alloc="${i}"]`).forEach(el=>{if(el!==e.target||raw!==''&&String(v)!==raw)el.value=v;});persist();updateCount();}});
document.addEventListener('submit',async e=>{e.preventDefault();if(await platform.onSubmit(e))return;let f=e.target,b=Object.fromEntries(new FormData(f));let submit=f.querySelector('button');if(submit)submit.disabled=true;try{if(f.id==='admin-form'){await api('/api/admin/login',b);$('#modal').innerHTML='';await sync(true);toast('Organiser console unlocked.');}else if(f.id==='profile-form'){if(state.nameLocked)throw Error('Your display name is locked');let name=String(b.name||'').replace(/\s+/g,' ').trim();if(!name||name.length>60)throw Error('Use a display name of 1–60 characters');nameDialog(2,name);}else if(f.id==='settings-form'){await api('/api/control',{action:'settings',settings:{pot:Number(b.pot),rounds:Number(b.rounds),fallback:Number(b.fallback),tie:b.tie}});await sync(true);toast('The stakes are set.');}}catch(e){let err=$('#form-error');if(err)err.textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.target.matches?.('input[data-alloc][type=number]')&&['-','+','e','E','.',','].includes(e.key))e.preventDefault();if(e.key==='Escape')$('#modal').innerHTML='';if(e.key==='Tab'&&$('#modal [role=dialog]')){let nodes=[...document.querySelectorAll('#modal button,#modal input,#modal select')].filter(n=>!n.disabled),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('change',async e=>{try{await platform.onChange(e);}catch(error){toast(error.message);}});
window.addEventListener('popstate',()=>{page=location.pathname.slice(1)||'overview';render();});
let authResult=new URLSearchParams(location.search).get('auth');if(authResult){history.replaceState({},'',location.pathname);setTimeout(()=>toast(authResult==='denied'?'This Google account is not on the sign-in list. Ask an organiser to add your email.':'Google sign-in did not finish. Please try again.'),300);}
await sync(true);let syncing=false;setInterval(()=>{if(syncing)return;syncing=true;sync().finally(()=>{syncing=false;});},2000);setInterval(clock,250);
